&#39;, sep = &#39;&#39;)<br>},output = function(x, options) {<br>  paste(&#39;\begin{lstlisting}[style=Routstyle]
&#39;, x,<br>        &#39;\end{lstlisting}
&#39;, sep = &#39;&#39;)<br>}, warning = hook_lst_bf, message = hook_lst_bf, error = hook_lst_bf)<br>set_header(highlight = &#39;&#39;)<br>knit_hooks$set(par=function(before, options, envir) {<br> if(before &amp;&amp; options$fig.show!=&#39;none&#39;) spar()}, crop=hook_pdfcrop)<br>options(replace.assign=TRUE)<br>% \SweaveOpts{highlight=FALSE, fig.path=figure/graphics-,<br>fig.align=center, fig.width=4, fig.height=3, fig.show=hold, par=TRUE}<br><br>My first question is how do I make knitr supress issuing<br> egin{kframe} ... \end{kframe}?  I use the following ugly trick for<br>now:<br><br>enewenvironment{kframe}{}{}  % let listings do shaded boxes<br><br>Secondly, raw R output is prefixed with &#39;##&#39;.  How do I suppress the<br>## in these R output lines?<br><br>Thanks very much,<br>Frank<br>

